import type { Config } from "tailwindcss";
import animate from "tailwindcss-animate";
import typography from "@tailwindcss/typography";

// Status and categorical hues read themed variables per role instead of fixed
// colours; src/styles/status-colors.css (generated by
// scripts/gen-status-colors.mjs) gives them Tailwind's own values in light and
// derived values in dark.
const STATUS_HUES = ["red", "amber", "green", "emerald", "blue", "sky", "zinc"];
const SHADES = [50, 100, 200, 300, 400, 500, 600, 700, 800, 900, 950];
const statusRole = (suffix: string) =>
	Object.fromEntries(
		STATUS_HUES.map((hue) => [
			hue,
			Object.fromEntries(SHADES.map((shade) => [shade, `rgb(var(--st-${hue}-${shade}${suffix}) / <alpha-value>)`])),
		]),
	);

export default {
	darkMode: ["class"],
	content: [
		"./pages/**/*.{ts,tsx}",
		"./components/**/*.{ts,tsx}",
		"./app/**/*.{ts,tsx}",
		"./src/**/*.{ts,tsx}",
	],
	prefix: "",
	theme: {
		container: {
			center: true,
			padding: '2rem',
			screens: {
				'2xl': '1400px'
			}
		},
		extend: {
			fontFamily: {
				// Distinctive editorial display face for marketing headings.
				// Body stays Inter (default) so the platform is unaffected.
				display: ['Fraunces', 'ui-serif', 'Georgia', 'serif'],
			},
			textColor: statusRole(""),
			borderColor: statusRole("-line"),
			colors: {
				...statusRole("-bg"),
				border: 'hsl(var(--border))',
				input: 'hsl(var(--input))',
				ring: 'hsl(var(--ring))',
				background: 'hsl(var(--background))',
				foreground: 'hsl(var(--foreground))',
				primary: {
					DEFAULT: 'hsl(var(--primary))',
					foreground: 'hsl(var(--primary-foreground))'
				},
				secondary: {
					DEFAULT: 'hsl(var(--secondary))',
					foreground: 'hsl(var(--secondary-foreground))'
				},
				destructive: {
					DEFAULT: 'hsl(var(--destructive))',
					foreground: 'hsl(var(--destructive-foreground))'
				},
				muted: {
					DEFAULT: 'hsl(var(--muted))',
					foreground: 'hsl(var(--muted-foreground))'
				},
				accent: {
					DEFAULT: 'hsl(var(--accent))',
					foreground: 'hsl(var(--accent-foreground))'
				},
				popover: {
					DEFAULT: 'hsl(var(--popover))',
					foreground: 'hsl(var(--popover-foreground))'
				},
				card: {
					DEFAULT: 'hsl(var(--card))',
					foreground: 'hsl(var(--card-foreground))'
				},
				sidebar: {
					DEFAULT: 'hsl(var(--sidebar-background))',
					foreground: 'hsl(var(--sidebar-foreground))',
					primary: 'hsl(var(--sidebar-primary))',
					'primary-foreground': 'hsl(var(--sidebar-primary-foreground))',
					accent: 'hsl(var(--sidebar-accent))',
					'accent-foreground': 'hsl(var(--sidebar-accent-foreground))',
					border: 'hsl(var(--sidebar-border))',
					ring: 'hsl(var(--sidebar-ring))'
				}
			},
			borderRadius: {
				lg: 'var(--radius)',
				md: 'calc(var(--radius) - 2px)',
				sm: 'calc(var(--radius) - 4px)'
			},
			keyframes: {
				'accordion-down': {
					from: {
						height: '0'
					},
					to: {
						height: 'var(--radix-accordion-content-height)'
					}
				},
				'accordion-up': {
					from: {
						height: 'var(--radix-accordion-content-height)'
					},
					to: {
						height: '0'
					}
				}
			},
			animation: {
				'accordion-down': 'accordion-down 0.2s ease-out',
				'accordion-up': 'accordion-up 0.2s ease-out'
			},
			// `prose` takes its colours from the theme tokens, which follow dark mode;
			// typography's own palette is fixed light-mode grey.
			typography: {
				DEFAULT: {
					css: {
						'--tw-prose-body': 'var(--text-1)',
						'--tw-prose-headings': 'var(--ink)',
						'--tw-prose-lead': 'var(--text-2)',
						'--tw-prose-links': 'var(--ink)',
						'--tw-prose-bold': 'var(--ink)',
						'--tw-prose-counters': 'var(--text-4)',
						'--tw-prose-bullets': 'var(--text-5)',
						'--tw-prose-hr': 'var(--line)',
						'--tw-prose-quotes': 'var(--ink)',
						'--tw-prose-quote-borders': 'var(--line)',
						'--tw-prose-captions': 'var(--text-4)',
						'--tw-prose-kbd': 'var(--ink)',
						'--tw-prose-code': 'var(--ink)',
						'--tw-prose-pre-code': 'var(--ink)',
						'--tw-prose-pre-bg': 'var(--sand)',
						'--tw-prose-th-borders': 'var(--line)',
						'--tw-prose-td-borders': 'var(--line-soft)'
					}
				}
			}
		}
	},
	plugins: [animate, typography],
} satisfies Config;
